    @InjectMocks
    private DocGenService docGenService;

    private final ObjectMapper objectMapper = new ObjectMapper();



    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(docGenService, "objectMapper", new ObjectMapper());
    }

    @Test
    void testMergeStageJsonPayloads() throws Exception {


        String stage1Payload = """
            {
              "criteria": [{
                "id": "Criterion 2",
                "requirementGroups": [
                    { 
                      "OCDS": { "id": "Group 1", "requirements": [] }, 
                      "nonOCDS": { "order": 1 } 
                    },
                    { 
                      "OCDS": { "id": "Group 2", "requirements": [] }, 
                      "nonOCDS": { "order": 2 } 
                    }
                ]
              }]
            }
            """;

        String stage2Payload = """
            {
              "criteria": [{
                "id": "Criterion 2",
                "requirementGroups": [
                    { 
                      "OCDS": { "id": "Group 1", "requirements": [] }, 
                      "nonOCDS": { "order": 1 } 
                    },
                    { 
                      "OCDS": { "id": "Group 2", "requirements": [] }, 
                      "nonOCDS": { "order": 2 } 
                    }
                ]
              }]
            }
            """;

        // Wrap them in Maps to simulate the data from ProcurementStageEvent
        Map<String, Object> stage1 = new HashMap<>();
        stage1.put("payload", stage1Payload);
        stage1.put("stageNumber", 1);
        stage1.put("stageDescription", "Description for Stage 1");

        Map<String, Object> stage2 = new HashMap<>();
        stage2.put("payload", stage2Payload);
        stage2.put("stageNumber", 2);
        stage2.put("stageDescription", "Description for Stage 2");

        List<Map<String, Object>> stageDataList = Arrays.asList(stage1, stage2);

        String resultJson = docGenService.mergeStageJsonPayloads(stageDataList);

        assertNotNull(resultJson);
        JsonNode root = objectMapper.readTree(resultJson);

        // Criterion 2 is at index 0 in our mock
        JsonNode groups = root.at("/criteria/0/requirementGroups");

        // Total groups: 2 from Stage 1 + 2 from Stage 2 = 4
        assertEquals(4, groups.size(), "Should have exactly 4 requirement groups merged");

        // Verify IDs: Stage 2 groups are re-indexed to .1
        assertEquals("Group 1", groups.get(0).at("/OCDS/id").asText());
        assertEquals("Group 1.1", groups.get(2).at("/OCDS/id").asText());

        // Verify Metadata Injection in Stage 2 Group 1.1 (index 2)
        JsonNode stage2Reqs = groups.get(2).at("/OCDS/requirements");

        // We expect 3 virtual requirements: STAGE_NUMBER, STAGE_TOTAL, STAGE_DESCRIPTION
        assertEquals(3, stage2Reqs.size(), "Should have 3 injected virtual requirements");

        String stageNum = "";
        String stageDesc = "";
        for (JsonNode r : stage2Reqs) {
            String title = r.at("/OCDS/title").asText();
            String value = r.at("/nonOCDS/options/0/value").asText();

            if ("STAGE_NUMBER".equals(title)) stageNum = value;
            if ("STAGE_DESCRIPTION".equals(title)) stageDesc = value;
        }

        assertEquals("2", stageNum, "Stage number should be 2 for the second payload");
        assertEquals("Description for Stage 2", stageDesc, "Stage description should match the metadata passed");

        // Verify Order (nonOCDS.order)
        // S1 G2 was order 2, so S2 G1.1 should be order 3
        assertEquals(3, groups.get(2).at("/nonOCDS/order").asInt(), "Order should be sequential across stages");
    }

    @Test
    void testMergeStageWithFourJsonPayloads() throws Exception {

        List<Map<String, Object>> stageDataList = new ArrayList<>();

        stageDataList.add(createStageMap(STAGE_1, 1, "Stage 1 Description"));
        stageDataList.add(createStageMap(STAGE_2, 2, "Stage 2 Description"));
        stageDataList.add(createStageMap(STAGE_3, 3, "Stage 3 Description"));
        stageDataList.add(createStageMap(STAGE_4, 4, "Stage 4 Description"));

        String resultJson = docGenService.mergeStageJsonPayloads(stageDataList);

        JsonNode root = objectMapper.readTree(resultJson);

        // Find Criterion 2
        JsonNode crit2 = null;
        for (JsonNode c : root.get("criteria")) {
            if ("Criterion 2".equals(c.get("id").asText())) {
                crit2 = c;
                break;
            }
        }

        assertNotNull(crit2, "Criterion 2 should exist");
        JsonNode groups = crit2.get("requirementGroups");

    /*
       EXPECTED COUNT:
       STAGE_1 has: Group 0, Group 1, Group 2 (3 groups)
       STAGE_2 adds: Group 1.1, Group 2.1 (2 groups)
       STAGE_3 adds: Group 1.2, Group 2.2 (2 groups)
       STAGE_4 adds: Group 1.3, Group 2.3 (2 groups)
       Total = 9 groups
    */
        assertEquals(9, groups.size(), "Total groups should be 9");

        // Verify re-indexing logic
        // Stage 1 (Indices 0,1,2): Group 0, Group 1, Group 2
        // Stage 2 (Indices 3,4): Group 1.1, Group 2.1
        // Stage 3 (Indices 5,6): Group 1.2, Group 2.2
        // Stage 4 (Indices 7,8): Group 1.3, Group 2.3

        assertEquals("Group 1.1", groups.get(3).at("/OCDS/id").asText());
        assertEquals("Group 1.3", groups.get(7).at("/OCDS/id").asText());
        assertEquals("Group 2.3", groups.get(8).at("/OCDS/id").asText());

        // Verify Metadata Injection for Stage 4 (Index 7 - Group 1.3)
        JsonNode group13Reqs = groups.get(7).at("/OCDS/requirements");

        boolean foundMetadata = false;
        for (JsonNode req : group13Reqs) {
            if ("STAGE_NUMBER".equals(req.at("/OCDS/title").asText()) &&
                    "4".equals(req.at("/nonOCDS/options/0/value").asText())) {
                foundMetadata = true;
                break;
            }
        }
        assertTrue(foundMetadata, "Metadata STAGE_NUMBER '4' should be present in Group 1.3");

        // Verify Stage Description for Stage 4
        String actualDesc = "";
        for (JsonNode req : group13Reqs) {
            if ("STAGE_DESCRIPTION".equals(req.at("/OCDS/title").asText())) {
                actualDesc = req.at("/nonOCDS/options/0/value").asText();
            }
        }

        assertThat(resultJson).isEqualToIgnoringWhitespace(EXPECTED_RESULT_JSON);
    }

    /**
     * Helper method to create the Map expected by the service
     */
    private Map<String, Object> createStageMap(String payload, int num, String desc) {
        Map<String, Object> map = new HashMap<>();
        map.put("payload", payload);
        map.put("stageNumber", num);
        map.put("stageDescription", desc);
        return map;
    }


